// An update a quit left staged is put in place, and a binary an update
// set aside is deleted, before anything else.
let finished_update = crate::self_update::at_launch();
// The full icon catalogue: the default bundle leaves out icons the app
// uses, such as the Edit and Reply badges', which then render blank.
let app = gpui_kit::application().with_assets(gpui_kit::assets::AllAssets);

app.run(|cx| {
    gpui_kit::init(cx);
    theme::init(cx);
    piton_syntax::init();
    ProjectDirectory::init(cx);
    ProjectLsp::init(cx);
    // The project open when the application last closed opens again.
    if let Some(last) = recent_projects::init(recent_projects::default_file(), cx) {
        ProjectDirectory::set(last, cx);
    }

    crate::self_update::Updates::init(finished_update, cx);

    // Never from within the window the action came from.
    cx.on_action(|_: &Quit, cx| main_window::MainWindow::quit_later(false, cx));
    cx.bind_keys([
        #[cfg(target_os = "macos")]
        KeyBinding::new("cmd-q", Quit, None),
        #[cfg(not(target_os = "macos"))]
        KeyBinding::new("ctrl-q", Quit, None),
    ]);
    main_window::bind_keys(cx);
    file_view::bind_keys(cx);
    settings_window::bind_keys(cx);

    // Closing the last window ends the application on every platform.
    cx.on_window_closed(|cx, _| {
        if cx.windows().is_empty() {
            cx.quit();
        }
    })
    .detach();

    MainWindow::open(cx).expect("failed to open main window");
        }
    };
